import{_ as a,a0 as d,w as r,s as p,ao as i,I as e,x as t,a1 as o,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何更改 Linux 控制台上的字體 | LCTT x X-CMD","titleTemplate":false,"description":"如何更改 Linux 控制台上的字體 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更改 Linux 控制台上的字體 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更改 Linux 控制台上的字體 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180104 How to Change Your Linux Console Fonts","title":"如何更改 Linux 控制台上的字體","tag":"201802","desc":""},"relativePath":"201802/20180104 How to Change Your Linux Console Fonts.md","filePath":"[post].md"}'),u={name:"201802/20180104 How to Change Your Linux Console Fonts.md"};function f(b,s,g,x,m,k){const n=d("Link");return r(),p("div",null,[s[43]||(s[43]=i('<h1 id="如何更改-linux-控制台上的字體" tabindex="-1">如何更改 Linux 控制台上的字體 <a class="header-anchor" href="#如何更改-linux-控制台上的字體" aria-label="Permalink to “如何更改 Linux 控制台上的字體”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/font-size_0.png?itok=d97vmyYa" alt=""></p><p>我嘗試儘可能的保持心靈祥和，然而總有一些事情讓我意難平，比如控制台字體太小了。記住我的話，朋友，有一天你的眼睛會退化，無法再看清你編碼時用的那些細小字體，到那時你就後悔莫及了。</p><p>幸好，Linux 死忠們，你可以更改控制台的字體。按照 Linux 一貫的尿性，不斷變化的 Linux 環境使得這個問題變得不太簡單明瞭，而 Linux 上也沒有字體管理這麼個東西，這使得我們很容易就被搞暈了。本文，我將會向你展示，我找到的更改字體的最簡方法。</p><h3 id="linux-控制台是個什麼鬼" tabindex="-1">Linux 控制台是個什麼鬼？ <a class="header-anchor" href="#linux-控制台是個什麼鬼" aria-label="Permalink to “Linux 控制台是個什麼鬼？”">​</a></h3><p>首先讓我們來澄清一下我們説的到底是個什麼東西。當我提到 Linux 控制台，我指的是 TTY1-6，即你從圖形環境用 <code>Ctrl-Alt-F1</code> 到 <code>F6</code> 切換到的虛擬終端。按下 <code>Ctrl+Alt+F7</code> 會切回圖形環境。(不過這些熱鍵已經不再通用，你的 Linux 發行版可能有不同的鍵映射。你的 TTY 的數量也可能不同，你圖形環境會話也可能不在 <code>F7</code>。比如，Fedora 的默認圖形會話是 <code>F2</code>，它只有一個額外的終端在 <code>F1</code>。) 我覺得能同時擁有 X 會話和終端會話實在是太酷了。</p><p>Linux 控制台是內核的一部分，而且並不運行在 X 會話中。它和你在沒有圖形環境的<ruby>無頭<rt>headless</rt></ruby>服務器中用的控制台是一樣的。我稱呼在圖形會話中的 X 終端為終端，而將控制台和 X 終端統稱為終端模擬器。</p>',7)),e("p",null,[s[1]||(s[1]=t("但這還沒完。Linux 終端從早期的 ANSI 時代開始已經經歷了長久的發展，多虧了 Linux framebuffer，它現在支持 Unicode 並且對圖形也有了有限的一些支持。而且出現了很多在控制台下運行的",-1)),o(n,{href:"https://linux.cn/article-9320-1.html"},{default:l(()=>[...s[0]||(s[0]=[t("多媒體應用",-1)])]),_:1}),s[2]||(s[2]=t("，這些我們在以後的文章中會提到。",-1))]),s[44]||(s[44]=e("h3",{id:"控制台截屏",tabindex:"-1"},[t("控制台截屏 "),e("a",{class:"header-anchor",href:"#控制台截屏","aria-label":"Permalink to “控制台截屏”"},"​")],-1)),e("p",null,[s[5]||(s[5]=t("獲取控制台截屏的最簡單方法是讓控制台跑在虛擬機內部。然後你可以在宿主系統上使用中意的截屏軟件來抓取。不過藉助 ",-1)),o(n,{href:"http://jwilk.net/software/fbcat"},{default:l(()=>[...s[3]||(s[3]=[t("fbcat",-1)])]),_:1}),s[6]||(s[6]=t(" 和 ",-1)),o(n,{href:"https://github.com/jwilk/fbcat/blob/master/fbgrab"},{default:l(()=>[...s[4]||(s[4]=[t("fbgrab",-1)])]),_:1}),s[7]||(s[7]=t(" 你也可以直接在控制台上截屏。",-1)),s[8]||(s[8]=e("code",null,"fbcat",-1)),s[9]||(s[9]=t(" 會創建一個可移植的像素映射格式（PPM）的圖像； 這是一個高度可移植的未壓縮圖像格式，可以在所有的操作系統上讀取，當然你也可以把它轉換成任何喜歡的其他格式。",-1)),s[10]||(s[10]=e("code",null,"fbgrab",-1)),s[11]||(s[11]=t(" 則是 ",-1)),s[12]||(s[12]=e("code",null,"fbcat",-1)),s[13]||(s[13]=t(" 的一個封裝腳本，用來生成一個 PNG 文件。很多人寫過多個版本的 ",-1)),s[14]||(s[14]=e("code",null,"fbgrab",-1)),s[15]||(s[15]=t("。每個版本的選項都有限而且只能創建截取全屏。",-1))]),s[45]||(s[45]=i('<p><code>fbcat</code> 的執行需要 root 權限，而且它的輸出需要重定向到文件中。你無需指定文件擴展名，只需要輸入文件名就行了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fbcat &gt; Pictures/myfile</span></span></code></pre></div><p>在 GIMP 中裁剪後，就得到了圖 1。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_10.png" alt=""></p><p><em>圖 1 ： 裁剪後查看</em></p><p>如果能在左邊空白處有一點填充就好了，如果有讀者知道如何實現請在留言框中告訴我。</p><p><code>fbgrab</code> 還有一些選項，你可以通過 <code>man fbgrab</code> 來查看，這些選項包括對另一個控制台進行截屏，以及延時截屏等。在下面的例子中可以看到，<code>fbgrab</code> 截屏跟 <code>fbcat</code> 截屏類似，只是你無需明確進行輸出重定性了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fbgrab Pictures/myOtherfile</span></span></code></pre></div><h3 id="查找字體" tabindex="-1">查找字體 <a class="header-anchor" href="#查找字體" aria-label="Permalink to “查找字體”">​</a></h3><p>就我所知，除了查看字體存儲目錄 <code>/usr/share/consolefonts/</code>（Debian 等），<code>/lib/kbd/consolefonts/</code> （Fedora），<code>/usr/share/kbd/consolefonts</code> （openSUSE）外沒有其他方法可以列出已安裝的字體了。</p><h3 id="更改字體" tabindex="-1">更改字體 <a class="header-anchor" href="#更改字體" aria-label="Permalink to “更改字體”">​</a></h3><p>可讀字體不是什麼新概念。我們應該尊重以前的經驗！可讀性是很重要的。可配置性也很重要，然而現如今卻不怎麼看重了。</p>',12)),e("p",null,[s[17]||(s[17]=t("在 Debian/Ubuntu 等系統上，可以運行 ",-1)),s[18]||(s[18]=e("code",null,"sudo dpkg-reconfigure console-setup",-1)),s[19]||(s[19]=t(" 來設置控制台字體，然後在控制台運行 ",-1)),s[20]||(s[20]=e("code",null,"setupcon",-1)),s[21]||(s[21]=t(" 命令來讓變更生效。",-1)),s[22]||(s[22]=e("code",null,"setupcon",-1)),s[23]||(s[23]=t(" 屬於 ",-1)),s[24]||(s[24]=e("code",null,"console-setup",-1)),s[25]||(s[25]=t(" 軟件包中的一部分。若你的 Linux 發行版中不包含該工具，可以在 ",-1)),o(n,{href:"https://software.opensuse.org/package/console-setup"},{default:l(()=>[...s[16]||(s[16]=[t("openSUSE",-1)])]),_:1}),s[26]||(s[26]=t(" 中下載到它。",-1))]),s[46]||(s[46]=i(`<p>你也可以直接編輯 <code>/etc/default/console-setup</code> 文件。下面這個例子中設置字體為 32 點大小的 Terminus Bold 字體，這是我的最愛，並且嚴格限制控制台寬度為 80 列。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTIVE_CONSOLES=&quot;/dev/tty[1-6]&quot;</span></span>
<span class="line"><span>CHARMAP=&quot;UTF-8&quot;</span></span>
<span class="line"><span>CODESET=&quot;guess&quot;</span></span>
<span class="line"><span>FONTFACE=&quot;TerminusBold&quot;</span></span>
<span class="line"><span>FONTSIZE=&quot;16x32&quot;</span></span>
<span class="line"><span>SCREEN_WIDTH=&quot;80&quot;</span></span></code></pre></div><p>這裏的 <code>FONTFACE</code> 和 <code>FONTSIZE</code> 的值來自於字體的文件名 <code>TerminusBold32x16.psf.gz</code>。是的，你需要反轉 <code>FONTSIZE</code> 中值的順序。計算機就是這麼搞笑。然後再運行 <code>setupcon</code> 來讓新配置生效。可以使用 <code>showconsolefont</code> 來查看當前所用字體的所有字符集。要查看完整的選項説明請參考 <code>man console-setup</code>。</p><h3 id="systemd" tabindex="-1">Systemd <a class="header-anchor" href="#systemd" aria-label="Permalink to “Systemd”">​</a></h3><p>Systemd 與 <code>console-setup</code> 不太一樣，除了字體之外，你無需安裝任何東西。你只需要編輯 <code>/etc/vconsole.conf</code> 然後重啓就行了。我在 Fedora 和 openSUSE 系統中安裝了一些額外的大字號的 Terminus 字體包，因為默認安裝的字體最大隻有 16 點而我想要的是 32 點。然後將 <code>/etc/vconsole.conf</code> 的內容修改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KEYMAP=&quot;us&quot;</span></span>
<span class="line"><span>FONT=&quot;ter-v32b&quot;</span></span></code></pre></div>`,6)),e("p",null,[s[28]||(s[28]=t("下週我們還將學習一些更加酷的控制台小技巧，以及一些在控制台上運行的",-1)),o(n,{href:"https://linux.cn/article-9320-1.html"},{default:l(()=>[...s[27]||(s[27]=[t("多媒體應用",-1)])]),_:1}),s[29]||(s[29]=t("。",-1))]),s[47]||(s[47]=e("hr",null,null,-1)),e("p",null,[s[31]||(s[31]=t("via: ",-1)),o(n,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/how-change-your-linux-console-fonts"},{default:l(()=>[...s[30]||(s[30]=[t("https://www.linux.com/learn/intro-to-linux/2018/1/how-change-your-linux-console-fonts",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=t("作者：",-1)),o(n,{href:"https://www.linux.com/users/cschroder"},{default:l(()=>[...s[32]||(s[32]=[t("Carla Schroder",-1)])]),_:1}),s[36]||(s[36]=t(" 譯者：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[33]||(s[33]=[t("lujun9972",-1)])]),_:1}),s[37]||(s[37]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[34]||(s[34]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[40]||(s[40]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[38]||(s[38]=[t("LCTT",-1)])]),_:1}),s[41]||(s[41]=t(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:l(()=>[...s[39]||(s[39]=[t("Linux中國",-1)])]),_:1}),s[42]||(s[42]=t(" 榮譽推出",-1))])])}const L=a(u,[["render",f]]);export{h as __pageData,L as default};
